SPLIT_SHA256 = "c09f7240396a33ca82977115af8d6067e571c0ec25c58a3c99b438ca2d2294b7"
GATES_SHA256 = "65151d60f69edc66d935d323813965906cacd57cb843eb3d70746348f16775ce"
SOURCE_MANIFEST_B64 = ""
GATES_ZLIB_B64 = ""
EXPECTED_EXPORTS = json.loads(base64.b64decode("", validate=True))
EXPECTED_EXPORT_STATS = json.loads(base64.b64decode("", validate=True))


def fail_if_export_bindings_incomplete() -> None:
    """Refuse all remote observation or mutation until all six exports are root-bound."""
    if len(EXPECTED_EXPORTS) != 6:
        raise RuntimeError("exactly six accepted, stopped teacher exports are required")
    expected = [
        ("fg19_t3_h384x2_e3_s3_v1", "train"),
        ("fg19_t3_h384x2_e3_s3_v1", "valid"),
        ("fg19_t3_h384x2_e3_s4_v1", "train"),
        ("fg19_t3_h384x2_e3_s4_v1", "valid"),
        ("fg19_t3_h384x2_e3_s5_v1", "train"),
        ("fg19_t3_h384x2_e3_s5_v1", "valid"),
    ]
    if [(x.get("run"), x.get("split")) for x in EXPECTED_EXPORTS] != expected:
        raise RuntimeError("export bindings are not in canonical S3/S4/S5 train/valid order")
    if len(EXPECTED_EXPORT_STATS) != len(EXPECTED_EXPORTS):
        raise RuntimeError("capture-time prediction stat bindings are incomplete")
    for export, stat in zip(EXPECTED_EXPORTS, EXPECTED_EXPORT_STATS):
        if set(stat) != {"capture_raw_sha256", "device", "inode", "bytes", "mtime_ns"}:
            raise RuntimeError("capture-time prediction stat binding has unexpected fields")
        if any(type(stat[name]) is not int for name in ("device", "inode", "bytes", "mtime_ns")):
            raise RuntimeError("capture-time prediction stat values must be JSON integers")
        capture_hash = stat["capture_raw_sha256"]
        if not isinstance(capture_hash, str) or len(capture_hash) != 64 or any(c not in "0123456789abcdef" for c in capture_hash):
            raise RuntimeError("invalid capture receipt hash for prediction stat binding")
        if stat["device"] <= 0 or stat["inode"] <= 0 or stat["mtime_ns"] <= 0 or stat["bytes"] != export["prediction_bytes"]:
            raise RuntimeError("capture-time prediction stat identity is malformed")
    required = (
        "acceptance_sha256", "exact_stop_raw_sha256", "invocation_id", "unit",
        "prediction_sha256", "prediction_bytes", "sidecar_sha256", "sidecar_bytes",
        "prediction_rows", "checkpoint_sha256", "provenance_sha256",
        "fit_membership_sha256", "normalization_identity",
    )
    missing = [
        f"{x['run']}:{x['split']}:{name}"
        for x in EXPECTED_EXPORTS for name in required if x.get(name) is None
    ]
    if missing:
        raise RuntimeError("accepted export binding is incomplete: " + ", ".join(missing))
    for x in EXPECTED_EXPORTS:
        for name in ("acceptance_sha256", "exact_stop_raw_sha256", "prediction_sha256", "sidecar_sha256"):
            value = x[name]
            if not isinstance(value, str) or len(value) != 64 or any(c not in "0123456789abcdef" for c in value):
                raise RuntimeError(f"invalid {name} for {x['run']}:{x['split']}")
        if not isinstance(x["prediction_bytes"], int) or not isinstance(x["sidecar_bytes"], int):
            raise RuntimeError("export sizes must be bound as JSON integers")


def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1 << 20), b""):
            digest.update(chunk)
    return digest.hexdigest()


def no_symlink(path: Path, *, directory: bool = False) -> None:
    if path.is_symlink() or not (path.is_dir() if directory else path.is_file()):
        raise RuntimeError(f"required physical path is missing or a symlink: {path}")


def no_symlink_ancestry(path: Path) -> None:
    """Reject path aliases through any component below the campaign volume."""
    try:
        relative = path.relative_to(B)
    except ValueError as error:
        raise RuntimeError(f"path escapes physical B: {path}") from error
    current = B
    if current.is_symlink():
        raise RuntimeError("campaign B root is a symlink")
    for part in relative.parts:
        current = current / part
        if current.is_symlink():
            raise RuntimeError(f"path ancestry contains symlink: {current}")


def source_inventory() -> dict[str, object]:
    raw_manifest = base64.b64decode(SOURCE_MANIFEST_B64, validate=True)
    if hashlib.sha256(raw_manifest).hexdigest() != SOURCE_MANIFEST_SHA256:
        raise RuntimeError("embedded canonical source manifest changed")
    manifest = json.loads(raw_manifest)
    if manifest.get("source_commit") != SOURCE_COMMIT or len(manifest.get("files", [])) != 167:
        raise RuntimeError("source manifest commit or 167-file inventory differs")
    no_symlink_ancestry(SOURCE)
    no_symlink(SOURCE, directory=True)
    expected = {item["path"]: item for item in manifest["files"]}
    if len(expected) != 167:
        raise RuntimeError("source manifest contains duplicate paths")
    observed_names: set[str] = set()
    for path in SOURCE.rglob("*"):
        if path.is_symlink():
            raise RuntimeError(f"staged source contains symlink: {path}")
        if path.is_file():
            observed_names.add(path.relative_to(SOURCE).as_posix())
    if observed_names != set(expected):
        raise RuntimeError("staged source inventory has missing or unexpected files")
    for name, item in expected.items():
        relative = Path(name)
        if relative.is_absolute() or ".." in relative.parts:
            raise RuntimeError(f"unsafe source path in pinned manifest: {name}")
        path = SOURCE / relative
        no_symlink(path)
        stat_result = path.stat()
        if stat_result.st_size != item["bytes"] or sha256(path) != item["sha256"]:
            raise RuntimeError(f"staged source differs from pinned Git inventory: {name}")
    return {
        "source_commit": SOURCE_COMMIT,
        "source_manifest_sha256": SOURCE_MANIFEST_SHA256,
        "source_files": len(expected),
        "source_bytes": sum(item["bytes"] for item in expected.values()),
    }


def export_descriptors() -> list[dict[str, object]]:
    """Check only accepted sidecars and NPY stats; builder owns payload hashing/finiteness."""
    manifest = json.loads(base64.b64decode(SOURCE_MANIFEST_B64, validate=True))
    no_symlink_ancestry(PREDICTIONS)
    no_symlink(PREDICTIONS, directory=True)
    if PREDICTIONS.stat().st_dev != B.stat().st_dev:
        raise RuntimeError("prediction exports are not on the physical B volume")
    source_map = {item["path"]: item["sha256"] for item in manifest["files"]}
    result = []
    for export_index, expected in enumerate(EXPECTED_EXPORTS):
        accepted_stat = EXPECTED_EXPORT_STATS[export_index]
        stem = f"pred_{expected['run']}_{expected['split']}"
        array = PREDICTIONS / f"{stem}.npy"
        sidecar = PREDICTIONS / f"{stem}.json"
        no_symlink_ancestry(array)
        no_symlink_ancestry(sidecar)
        no_symlink(array)
        no_symlink(sidecar)
        array_stat = array.stat()
        sidecar_stat = sidecar.stat()
        if (
            array_stat.st_dev != B.stat().st_dev
            or array_stat.st_dev != accepted_stat["device"]
            or array_stat.st_ino != accepted_stat["inode"]
            or array_stat.st_size != expected["prediction_bytes"]
            or array_stat.st_size != accepted_stat["bytes"]
            or array_stat.st_mtime_ns != accepted_stat["mtime_ns"]
        ):
            raise RuntimeError(f"prediction array stat differs from accepted capture identity: {stem}")
        if sidecar_stat.st_dev != B.stat().st_dev or sidecar_stat.st_size != expected["sidecar_bytes"]:
            raise RuntimeError(f"prediction sidecar stat differs from accepted output: {stem}")
        raw = sidecar.read_bytes()
        if len(raw) > 128 * 1024 or hashlib.sha256(raw).hexdigest() != expected["sidecar_sha256"]:
            raise RuntimeError(f"prediction sidecar is not the accepted bounded JSON: {stem}")
        doc = json.loads(raw)
        if (
            doc.get("run") != expected["run"]
            or doc.get("split") != expected["split"]
            or doc.get("epoch") != 2
            or doc.get("checkpoint_sha256") != expected["checkpoint_sha256"]
            or doc.get("prediction_sha256") != expected["prediction_sha256"]
            or doc.get("campaign_split_manifest_sha256") != SPLIT_SHA256
            or doc.get("campaign_export_scope") != "fit"
            or doc.get("feature_only") is not True
            or doc.get("normalization_identity") != expected["normalization_identity"]
            or not isinstance(doc.get("row_groups"), list)
            or len(doc["row_groups"]) != expected["prediction_rows"]
        ):
            raise RuntimeError(f"accepted prediction sidecar identity mismatch: {stem}")
        semantic_pins = doc.get("source_sha256")
        if not isinstance(semantic_pins, dict) or len(semantic_pins) != 18:
            raise RuntimeError(f"source pin set differs from the reviewed 18-file map: {stem}")
        if any(source_map.get(name) != digest for name, digest in semantic_pins.items()):
            raise RuntimeError(f"prediction sidecar source pins differ from 167-file manifest: {stem}")
        result.append({
            "run": expected["run"],
            "split": expected["split"],
            "acceptance_sha256": expected["acceptance_sha256"],
            "exact_stop_raw_sha256": expected["exact_stop_raw_sha256"],
            "native_unit": expected["unit"],
            "invocation_id": expected["invocation_id"],
            "prediction_sha256_producer_authority": expected["prediction_sha256"],
            "accepted_capture_raw_sha256": accepted_stat["capture_raw_sha256"],
            "accepted_prediction_stat": accepted_stat,
            "prediction_stat_only": {
                "path": str(array), "device": array_stat.st_dev, "inode": array_stat.st_ino,
                "bytes": array_stat.st_size, "mtime_ns": array_stat.st_mtime_ns,
            },
            "sidecar_sha256": expected["sidecar_sha256"],
            "sidecar_stat": {
                "path": str(sidecar), "device": sidecar_stat.st_dev,
                "inode": sidecar_stat.st_ino, "bytes": sidecar_stat.st_size,
                "mtime_ns": sidecar_stat.st_mtime_ns,
            },
            "checkpoint_sha256": expected["checkpoint_sha256"],
            "provenance_sha256": expected["provenance_sha256"],
            "fit_membership_sha256": expected["fit_membership_sha256"],
        })
    return result


def main() -> None:
    """Run read-only gates, then submit the one bounded CPU cache builder."""
    if not __debug__ or sys.flags.optimize != 0:
        raise RuntimeError("cache admission requires normal Python assertions (no -O/PYTHONOPTIMIZE)")
    fail_if_export_bindings_incomplete()
    gates_source = zlib.decompress(base64.b64decode(GATES_ZLIB_B64, validate=True))
    if hashlib.sha256(gates_source).hexdigest() != GATES_SHA256:
        raise RuntimeError("reused reviewed gate source hash changed")
    gates = {"__name__": "reused_readonly_profile_gates"}
    exec(compile(gates_source, "reviewed_profile_readonly_gates", "exec"), gates)
    gates["B"] = B
    gates["DATA"] = DATA
    gates["FIT_MEMORY"] = FIT_MEMORY

    if B.is_symlink() or not B.is_dir() or DATA.resolve(strict=True) != B / "data":
        raise RuntimeError("campaign/data roots are not the expected physical B tree")
    if not PYTHON.is_file() or not os.access(PYTHON, os.X_OK):
        raise FileNotFoundError("pinned project interpreter is unavailable")
    source = source_inventory()
    no_symlink(CONTRACT)
    contract_raw = CONTRACT.read_bytes()
    if hashlib.sha256(contract_raw).hexdigest() != CONTRACT_SHA256:
        raise RuntimeError("frozen cleanfold execution contract changed")
    contract = json.loads(contract_raw)
    if (
        contract.get("schema") != "fg19.teacher-cache-execution-contract.v1"
        or contract.get("source_teacher_commit") != TEACHER_COMMIT
        or contract.get("split_sha256") != SPLIT_SHA256
        or contract.get("status") != "PRE_OUTCOME_CONTRACT_NEW_INFERENCE_NOT_RUN"
        or contract.get("teacher_order") != [3, 4, 5]
    ):
        raise RuntimeError("frozen teacher-cache contract identity differs")
    metadata_checks = [{"path": str(CONTRACT), "bytes": len(contract_raw), "sha256": CONTRACT_SHA256}]
    if len(contract.get("teachers", [])) != 3:
        raise RuntimeError("contract must bind the three ordered original teacher fits")
    for teacher in contract["teachers"]:
        relative = Path(teacher["acceptance_path"])
        if relative.is_absolute() or ".." in relative.parts:
            raise RuntimeError("unsafe original teacher acceptance path in contract")
        receipt_path = ACCEPTANCE_ROOT / relative
        no_symlink_ancestry(receipt_path)
        no_symlink(receipt_path)
        raw_receipt = receipt_path.read_bytes()
        if hashlib.sha256(raw_receipt).hexdigest() != teacher["acceptance_sha256"]:
            raise RuntimeError(f"original teacher acceptance changed: {teacher['run']}")
        receipt = json.loads(raw_receipt)
        if (
            receipt.get("status") != "ACCEPTED"
            or receipt.get("run_name") != teacher["run"]
            or receipt.get("selected_epoch") != 2
            or teacher.get("epoch") != 2
        ):
            raise RuntimeError(f"original teacher acceptance identity differs: {teacher['run']}")
        metadata_checks.append({
            "path": str(receipt_path), "bytes": len(raw_receipt),
            "sha256": teacher["acceptance_sha256"], "run": teacher["run"],
        })
    if len(metadata_checks) != 4:
        raise RuntimeError("expected four unchanged contract/teacher metadata JSON files")
    no_symlink_ancestry(SPLIT)
    no_symlink(SPLIT)
    if SPLIT.stat().st_size != 1_388_846 or sha256(SPLIT) != SPLIT_SHA256:
        raise RuntimeError("canonical B/splits/fold0.json changed")
    data_identity = gates["_data_identity"]()
    parent, populated, cgroup = gates["_parent"]()
    scratch_path = B / "research_tmp"
    no_symlink_ancestry(scratch_path)
    no_symlink(scratch_path, directory=True)
    if scratch_path.stat().st_dev != B.stat().st_dev:
        raise RuntimeError("cache scratch is not on the expected physical B volume")
    scratch = gates["_run"](["findmnt", "-T", str(scratch_path), "-n", "-o", "FSTYPE,SOURCE,TARGET"]).strip()
    if not scratch or scratch.split()[0] in {"tmpfs", "ramfs"}:
        raise RuntimeError("cache scratch is not physical disk")
    output_bytes = 11_940 * 20_000 * 2 * 4
    if output_bytes != 1_910_400_000:
        raise RuntimeError("unexpected fixed cache output estimate")
    disk = os.statvfs(B / "research_tmp")
    free_bytes = disk.f_bavail * disk.f_frsize
    floor = 25 * (1 << 30)
    if free_bytes - output_bytes < floor:
        raise RuntimeError("physical scratch cannot preserve 25 GiB after the cache output")
    if any(os.path.lexists(path) for path in (OUTPUT, PARTIAL, EVIDENCE, B / "runtime/STOP_ADMISSION.json")):
        raise FileExistsError("cache output/partial/evidence exists or campaign admission is stopped")
    if gates["_unit"](UNIT, ["LoadState"]).get("LoadState") != "not-found":
        raise RuntimeError("exact cache unit already exists; never retry an unknown outcome")
    exports = export_descriptors()
    # Recheck create-only targets after all read-only validation.
    if any(os.path.lexists(path) for path in (OUTPUT, PARTIAL, EVIDENCE)):
        raise FileExistsError("cache destination appeared during admission")

    EVIDENCE.mkdir(mode=0o700)
    admission = {
        "schema": "fg19_teacher_cache_cpu_admission.v1",
        "created_utc": dt.datetime.now(dt.UTC).isoformat(),
        "status": "ADMITTED_CPU_CACHE_BUILD",
        "source": source,
        "contract_sha256": CONTRACT_SHA256,
        "unchanged_contract_and_teacher_metadata": metadata_checks,
        "split_manifest": {"path": str(SPLIT), "bytes": 1_388_846, "sha256": SPLIT_SHA256},
        "data_identity_stats_only": data_identity,
        "parent": parent,
        "populated_campaign_descendants": populated,
        "parent_memory_events": (cgroup / "memory.events").read_text(),
        "parent_memory_events_local": (cgroup / "memory.events.local").read_text(),
        "accepted_stopped_teacher_exports": exports,
        "scratch_filesystem": scratch,
        "disk": {
            "path": str(B / "research_tmp"), "free_before_bytes": free_bytes,
            "estimated_output_bytes": output_bytes, "free_after_estimate_bytes": free_bytes - output_bytes,
            "minimum_free_after_bytes": floor,
        },
        "output": str(OUTPUT),
        "partial": str(PARTIAL),
        "unit": UNIT,
        "resource_reservation": {
            "cpu_quota": "50%", "memory_high_bytes": MEMORY_HIGH,
            "memory_max_bytes": FIT_MEMORY, "swap_max_bytes": 0,
            "runtime_max_seconds": RUNTIME_MAX, "torch_threads": 1,
            "blas_threads": 1, "cuda_visible_devices": "",
        },
        "scientific_scope": {
            "new_fits": 0, "teacher_order": [3, 4, 5], "epoch": 2,
            "arithmetic": "raw FP32 arithmetic mean in fixed S3/S4/S5 order; 0.8125 applied once",
            "clipping": "none during cache construction",
            "finite_validation": "streamed by the canonical cache builder; not performed by admission",
            "prediction_payload_read_or_hashed_by_admission": False,
            "model_or_checkpoint_deserialized": False,
        },
        "command": [
            str(PYTHON), "-u", str(SOURCE / "scripts/build_distill_cache.py"),
            "--data-root", str(DATA), "--teacher-cache-root", str(PREDICTIONS),
            "--checkpoint-root", str(DATA / "artifacts/runs"),
            "--cache-profile", "cleanfold_homogeneous_strong_t3_v1",
            "--cleanfold-contract", str(CONTRACT), "--cleanfold-contract-sha256", CONTRACT_SHA256,
            "--acceptance-root", str(ACCEPTANCE_ROOT), "--split-manifest", str(SPLIT),
            "--output", str(OUTPUT),
            "--teacher", "strong=fg19_t3_h384x2_e3_s3_v1@ep2*0.1",
            "--teacher", "strong=fg19_t3_h384x2_e3_s4_v1@ep2*0.1",
            "--teacher", "strong=fg19_t3_h384x2_e3_s5_v1@ep2*0.1",
            "--homogeneous-family", "strong", "--expected-coefficient-sum", "0.8125",
            "--chunk-sequences", "8", "--output-profile", "homogeneous-only",
            "--output-budget-gb", "30", "--min-free-gb", "25",
        ],
    }
    gates["_write"](EVIDENCE / "ADMISSION.json", admission)

    env = {
        "PYTHONPATH": str(SOURCE / "src"),
        "PYTHONDONTWRITEBYTECODE": "1",
        "PYTHONOPTIMIZE": "",
        "WNN_PROJECT_ROOT": str(DATA),
        "WNN_PORTABLE_DATA_MANIFEST": str(B / "support-source/terminal-v1/PORTABLE_SOURCES.json"),
        "WNN_THREADS": "1",
        "OMP_NUM_THREADS": "1",
        "OPENBLAS_NUM_THREADS": "1",
        "MKL_NUM_THREADS": "1",
        "NUMEXPR_NUM_THREADS": "1",
        "CUDA_VISIBLE_DEVICES": "",
        "TMPDIR": str(B / "research_tmp"),
        "WNN_TMP_ROOT": str(B / "research_tmp"),
    }
    systemd = [
        "systemd-run", "--user", "--unit=" + UNIT,
        "--property=Type=exec", "--property=RemainAfterExit=yes",
        "--property=Slice=wnn-campaign.slice", "--property=CPUQuota=50%",
        "--property=MemoryHigh=" + str(MEMORY_HIGH), "--property=MemoryMax=" + str(FIT_MEMORY),
        "--property=MemorySwapMax=0", "--property=RuntimeMaxSec=" + str(RUNTIME_MAX),
        "--property=TimeoutStopSec=45",
        "--property=StandardOutput=append:" + str(EVIDENCE / "unit.log"),
        "--property=StandardError=append:" + str(EVIDENCE / "unit.log"),
        "--working-directory=" + str(SOURCE),
    ]
    systemd.extend("--setenv=" + key + "=" + value for key, value in env.items())
    systemd.extend(admission["command"])
    def capture_output(value: str | bytes | None) -> dict[str, object]:
        if isinstance(value, bytes):
            return {"encoding": "base64", "value": base64.b64encode(value).decode("ascii")}
        if isinstance(value, str):
            return {"encoding": "utf-8", "value": value}
        return {"encoding": "none", "value": None}

    try:
        result = subprocess.run(systemd, capture_output=True, text=True, timeout=30)
        submission = {"returncode": result.returncode,
                      "stdout_capture": capture_output(result.stdout),
                      "stderr_capture": capture_output(result.stderr),
                      "outcome": "submitted" if result.returncode == 0 else "unknown_or_failed"}
    except subprocess.TimeoutExpired as error:
        submission = {"returncode": None,
                      "stdout_capture": capture_output(error.stdout),
                      "stderr_capture": capture_output(error.stderr),
                      "outcome": "unknown"}
    props = ["InvocationID", "ExecStart", "ActiveState", "SubState", "MainPID", "ControlGroup"]
    try:
        show = subprocess.run(
            ["systemctl", "--user", "show", "--all", UNIT, *sum((["-p", key] for key in props), [])],
            capture_output=True, text=True, timeout=10,
        )
        show_record = {"returncode": show.returncode,
                       "stdout_capture": capture_output(show.stdout),
                       "stderr_capture": capture_output(show.stderr), "timed_out": False}
    except subprocess.TimeoutExpired as error:
        show_record = {"returncode": None,
                       "stdout_capture": capture_output(error.stdout),
                       "stderr_capture": capture_output(error.stderr), "timed_out": True}
    launch = {
        "schema": "fg19_teacher_cache_cpu_launch.v1",
        "created_utc": dt.datetime.now(dt.UTC).isoformat(),
        "unit": UNIT,
        "submission": submission,
        "systemctl_after_submission": show_record,
        "unknown_outcome_policy": "never retry; inspect only this exact unit and evidence directory",
    }
    gates["_write"](EVIDENCE / "LAUNCH.json", launch)
    print(json.dumps({name: base64.b64encode((EVIDENCE / name).read_bytes()).decode("ascii")
                      for name in ("ADMISSION.json", "LAUNCH.json")}))


if __name__ == "__main__":
    main()
